BEGIN READ ONLY;
SET LOCAL statement_timeout='15s';
SELECT COALESCE(json_agg(x),'[]'::json) FROM (SELECT CASE WHEN process_id=ANY(ARRAY['advisory_desk_opinion','advisory_desk_synthesis','aegis_steph_review','aegis_synthesis','alex_cio_escalation','alex_cio_synthesis','architecture_review','broker_cloud_oversight','cloud_consensus_verdict','cloud_review','deepseek_flash_operator_smoke','cio_policy_field_advisor','directive_keyword_enhancer','grok_execution_review','guardian_risk_critique','hermes_analyst_coverage','hermes_cross_source_synthesizer','hermes_external_research','hermes_scalp_review','hermes_tag_engine','holding_protection_advisor','holding_protection_advisor_batch','holdings_llm_refresh','iris_taxonomy_agent','journal_ask','l3_judgment_author','l3_independent_critic','ledger_tax_critique','llm_intelligence_enrichment','maria_research_critique','morgan_wealth_synthesis','multi_tier_trade_reviewer','oauth_lane_keepalive','options_ensemble','paper_trade_advisory','pipeline_health_diagnosis','portfolio_ai_analyst','portfolio_ask','portfolio_monthly_report','portfolio_orchestrator','portfolio_weekly_report','reflective_critic_flash','reporting_grok_editorial','rotation_grok_review','rotation_oversight','steph_allocation_review','stop_drift_alert','strategy_planner','think_tank_signal_miner','topic_curator','topic_ingestion','ri_narrative_enrich','topic_research_synthesizer','unregistered','watchlist_agent_debate_flash','watchlist_agent_flash_extract','watchlist_cio_synthesis','watchlist_cio_synthesis_cron','grok_stop_review','watchlist_entry_planner','watchlist_maria_flash_narrative','watchlist_maria_priority','watchlist_agent_oauth_fallback','watchlist_risk_flash_narrative','watchlist_steph_flash_narrative','options_thesis_cio_review','cio_operator_reply','cio_plan_enrichment','cio_prompt_judge','research_circle_analyzer','hermes_cloud_json','hermes_usefulness_score','cio_hermes_research','hermes_golden_judge','local_llm_compat','contradiction_adjudicator','n8n_material_digest_draft','n8n_ops_summary_draft','n8n_lane_failure_diagnosis','incubator_llm_screener','journal_review_builder','portfolio_lookthrough_themes','hermes_usefulness_score_n8n','proposal_llm_review','defense_weekly_oversight','analyst_report_editorial','analyst_report_critique','due_diligence_questions','blind_review_runner','cio_ask_deep_research']) THEN process_id ELSE 'UNMAPPED' END AS process_id, model_lane, model_name, count(*) AS calls, count(*) FILTER (WHERE NOT success) AS failures, COALESCE(sum(estimated_cost_usd) FILTER (WHERE cost_basis='provider_usage_x_registry_snapshot'),0) AS trusted_usd, count(*) FILTER (WHERE cost_basis IS DISTINCT FROM 'provider_usage_x_registry_snapshot' AND estimated_cost_usd>0) AS untrusted_cost_rows, COALESCE(sum(tokens_in),0) AS tokens_in, COALESCE(sum(tokens_out),0) AS tokens_out FROM llm_consumption_log WHERE created_at>=date_trunc('day', now() AT TIME ZONE 'America/New_York') AT TIME ZONE 'America/New_York' AND created_at<=now() AND process_id !~ '^(test_|test-|pytest_|fixture_|caprace_|test$)' GROUP BY 1,2,3 ORDER BY 1,2,3) x;
ROLLBACK;
